from taf.rfrl.l3_call.enviornment.classical_env.classical_env import ClassicalEnv


class ClassicalEnvEnb(ClassicalEnv):

    def __init__(self):
        super(ClassicalEnvEnb, self).__init__()
        self._ran = "classical"
        self._mode = ""
        self._node = "enb"
        self._delta_id = "l3_call_enb_delta_id"
        self._connection_alias = "l3_call_{}".format(self._node)

    def __str__(self):
        return "ClassicalEnvEnb instance for ran={}, node={}".format(self._ran, self._node)

    def _make_cell_ids_dict(self):
        return {"enb_cell": self._cell.id}
